use std::fs

fn all_digits(s: string) -> bool {
    if s.len() == 0 { return false }
    for c in s.chars() {
        if c < '0' || c > '9' { return false }
    }
    true
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut users: Vec<string> = []
    let mut counts: Vec<int> = []
    let mut totals: Vec<int> = []
    let mut ua: Vec<string> = []
    let mut an: Vec<string> = []
    let mut ac: Vec<int> = []
    let mut bad = 0
    for line in text.lines() {
        let parts: Vec<string> = line.split(" ").collect()
        if parts.len() != 3 || !all_digits(parts[2]) {
            bad += 1
            continue
        }
        let s: int = parts[2].parse::<int>().unwrap_or(0)
        let mut idx: int = -1
        let mut i: int = 0
        while i < users.len() as int {
            if users[i] == parts[0] { idx = i }
            i += 1
        }
        if idx < 0 {
            users.push(parts[0])
            counts.push(0)
            totals.push(0)
            idx = users.len() as int - 1
        }
        counts[idx] = counts[idx] + 1
        totals[idx] = totals[idx] + s
        let mut k: int = -1
        let mut j: int = 0
        while j < ua.len() as int {
            if ua[j] == parts[0] && an[j] == parts[1] { k = j }
            j += 1
        }
        if k < 0 {
            ua.push(parts[0])
            an.push(parts[1])
            ac.push(0)
            k = ua.len() as int - 1
        }
        ac[k] = ac[k] + 1
    }
    let n: int = users.len() as int
    let mut order: Vec<int> = []
    let mut q: int = 0
    while q < n {
        order.push(q)
        q += 1
    }
    let mut x: int = 0
    while x < n {
        let mut y: int = 0
        while y < n - 1 - x {
            let a = order[y]
            let b = order[y + 1]
            if totals[a] < totals[b] || (totals[a] == totals[b] && users[a] > users[b]) {
                order[y] = b
                order[y + 1] = a
            }
            y += 1
        }
        x += 1
    }
    for o in order {
        let mut best = ""
        let mut bc: int = 0
        let mut m: int = 0
        while m < ua.len() as int {
            if ua[m] == users[o] {
                if ac[m] > bc || (ac[m] == bc && an[m] < best) {
                    bc = ac[m]
                    best = an[m]
                }
            }
            m += 1
        }
        println("${users[o]} ${counts[o]} ${totals[o]} ${best}")
    }
    println("malformed: ${bad}")
}

